def _is_field_custom_column(field, db):
    if field[0] == '*':
        if field.endswith('_index'):
            fkey = field[1:-len('_index')]
            return fkey in db.custom_column_label_map
        else:
            return field[1:] in db.custom_column_label_map
    return False


def _get_custom_column_label(field, db):
    if field[0] == '*':
        if field.endswith('_index'):
            fkey = field[1:-len('_index')]
            num = db.custom_column_label_map[fkey]['num']
            return '%d_index'%num
        else:
            return db.custom_column_label_map[field[1:]]['num']
    return field


def _is_field_id(field):
    return field == 'id'


def _is_field_title(field):
    return field == 'title'


def _is_field_not_id(field):
    return not _is_field_id(field)


def _is_field_not_title(field):
    return not _is_field_title(field)


def _is_field_not_id_or_title(field):
    return not _is_field_id(field) and not _is_field_title(field)


def _is_field_not_id_or_title_or_custom(field, db):
